mapper.select:
SELECT
t.label_id as labelId, t.industry_code, t.app_ver_code,
t.label_name as labelName,
rel.id as labelRelId,
(
case when length(IFNULL(rel.id, '')) = 0
then 0 else 1 end
) as labelStatus
FROM vm_tenant_label_config as t
left join vm_device_labels_rel as rel
on t.label_id = rel.label_id and t.tenant_id = rel.tenant_id and rel.device_code = #{deviceCode}
where t.tenant_id = #{tenantId}

    and t.industry_code = #{industryCode}

SELECT t.label_id as labelId, t.label_name as labelName FROM vm_tenant_label_config as t
where t.tenant_id = #{tenantId}

    and t.industry_code = #{industryCode}

select count(*) from vm_tenant_label_config
where tenant_id = #{tenantId} and industry_code = #{industryCode} and label_name = #{labelName}

    and label_id != #{labelId}

select l.label_id, l.label_name, r.device_code from vm_device_labels_rel r inner join vm_tenant_label_config l on r.label_id = l.label_id where l.tenant_id = #{param.tenantId} and l.industry_code = #{param.industryCode} and r.device_code in
#{item}
order by r.device_code, r.label_id

select l.label_id labelId, l.label_name labelName, t.id labelTypeId, t.label_type_name labelTypeName
from vm_tenant_label_type_config t
left join vm_tenant_label_config l on l.label_type_id = t.id and l.delete_flag = 0 and l.tenant_id = #{tenantId} and l.industry_code = #{industryCode}
where t.delete_flag = 0 and t.tenant_id = #{tenantId} and t.industry_code = #{industryCode}
order by t.create_time, t.id, l.create_time, l.label_id;

select label_id, tenant_id, industry_code
from vm_tenant_label_config
where label_id = #{labelId}
